package com.learningspace;
import android.app.*;import android.appwidget.*;import android.content.*;import android.content.res.Configuration;import android.os.*;
public class WidgetConfigActivity extends Activity{@Override public void onCreate(Bundle state){boolean dark=(getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES;setTheme(dark?android.R.style.Theme_Material_NoActionBar:android.R.style.Theme_Material_Light_NoActionBar);super.onCreate(state);int id=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);setResult(RESULT_CANCELED);if(id==AppWidgetManager.INVALID_APPWIDGET_ID){finish();return;}String[] values={"app","light","forest","system"};new AlertDialog.Builder(this).setTitle("Choose your widget style").setItems(new String[]{"Follow the app","Light · warm paper","Forest · quiet dark","Follow the phone"},(dialog,which)->{getSharedPreferences("widgets",0).edit().putString("theme_"+id,values[which]).apply();LearningWidget.updateAll(this);setResult(RESULT_OK,new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id));finish();}).setOnCancelListener(d->finish()).show();}}
